package net.civeira.phylax.common.security;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.function.Consumer;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import jakarta.enterprise.inject.Instance;
import net.civeira.phylax.common.security.impl.ActorImpl;
import net.civeira.phylax.common.security.scope.Kind;
import net.civeira.phylax.common.security.scope.ResourceDescription;
import net.civeira.phylax.common.security.scope.ScopeDescription;

@DisplayName("Rbac with only inactive stores")
class RbacInactiveStoreUnitTest {

  private RbacStore store;
  private Rbac rbac;

  @BeforeEach
  @SuppressWarnings("unchecked")
  void setUp() {
    store = mock(RbacStore.class);
    when(store.isActive()).thenReturn(false);
    Instance<RbacStore> manager = mock(Instance.class);
    doAnswer(invocation -> {
      Consumer<RbacStore> action = invocation.getArgument(0);
      action.accept(store);
      return null;
    }).when(manager).forEach(any());
    rbac = new Rbac(manager, true);
  }

  @Test
  @DisplayName("Should not register actions on inactive stores")
  void shouldSkipInactiveStoresOnRegisterAction() {
    ResourceDescription resource = ResourceDescription.builder().name("tenant").build();
    ScopeDescription action =
        ScopeDescription.builder().name("read").kind(Kind.values()[0]).build();

    rbac.registerResourceAction(resource, action);

    verify(store, never()).registerResourceAction(any(), any());
  }

  @Test
  @DisplayName("Should fall back to the default policy when no store is active")
  void shouldUseDefaultPolicyWithoutActiveStores() {
    Actor actor = ActorImpl.builder().build();

    assertTrue(rbac.checkAllow(actor, "tenant", "read").isAllowed());
    assertEquals(0, rbac.inaccessibleFields(actor, "tenant", "view").size());
  }
}
